def _pairs(blob, combine):
    out = {}
    for record in blob.split(';'):
        if not record:
            continue
        first, second, value = record.split(',')
        out[(int(first, 16), int(second, 16))] = combine(value)
    return out


def _ranges(blob):
    out = []
    for record in blob.split(';'):
        if not record:
            continue
        first, last, value = record.split(',')
        out.append((int(first, 16), int(last, 16), value))
    return out


def _at(rows, number):
    low = 0
    high = len(rows)
    while low < high:
        middle = (low + high) // 2
        if rows[middle][1] < number:
            low = middle + 1
        else:
            high = middle
    if low < len(rows) and rows[low][0] <= number:
        return rows[low][2]
    return ''


_categories = None
_bidi = None
_combining = None
_decompositions = None
_canonical = None
_compat = None
_compositions = None


def _category_rows():
    global _categories
    if _categories is None:
        _categories = _ranges(_CATEGORY_DATA)
    return _categories


def _bidi_rows():
    global _bidi
    if _bidi is None:
        _bidi = _ranges(_BIDI_DATA)
    return _bidi


def _combining_map():
    global _combining
    if _combining is None:
        table = {}
        for record in _COMBINING_DATA.split(';'):
            if not record:
                continue
            point, level = record.split(',')
            table[int(point, 16)] = int(level)
        _combining = table
    return _combining


def _decomposition_map():
    global _decompositions
    if _decompositions is None:
        table = {}
        for record in _DECOMPOSITION_DATA.split('\n'):
            if not record:
                continue
            point, raw = record.split('\t')
            table[int(point, 16)] = raw
        _decompositions = table
    return _decompositions


def _composition_map():
    global _compositions
    if _compositions is None:
        _compositions = _pairs(_COMPOSITION_DATA, lambda text: int(text, 16))
    return _compositions


def _expansion_map(blob):
    table = {}
    for record in blob.split('\n'):
        if not record:
            continue
        point, written = record.split('\t')
        table[int(point, 16)] = [int(word, 16) for word in written.split()]
    return table


def _canonical_map():
    global _canonical
    if _canonical is None:
        _canonical = _expansion_map(_CANONICAL_DATA)
    return _canonical


def _compat_map():
    global _compat
    if _compat is None:
        _compat = _expansion_map(_COMPAT_DATA)
    return _compat


def _want(letter):
    if not isinstance(letter, str) or len(letter) != 1:
        raise TypeError('a single Unicode character is required')
    return ord(letter)


def _order(points, ranks):
    placed = 1
    while placed < len(points):
        rank = ranks.get(points[placed], 0)
        if rank:
            back = placed
            while back > 0 and ranks.get(points[back - 1], 0) > rank:
                points[back - 1], points[back] = points[back], points[back - 1]
                back -= 1
        placed += 1


def _meld(points, ranks, joins):
    folded = []
    root = None
    previous = 0
    for point in points:
        rank = ranks.get(point, 0)
        if root is not None and (previous == 0 or previous < rank):
            first = folded[root]
            made = None
            if 0x1100 <= first < 0x1113 and 0x1161 <= point < 0x1176:
                made = 0xAC00 + ((first - 0x1100) * 21 + (point - 0x1161)) * 28
            elif 0xAC00 <= first < 0xD7A4 and (first - 0xAC00) % 28 == 0 and 0x11A8 <= point < 0x11C3:
                made = first + (point - 0x11A7)
            else:
                made = joins.get((first, point))
            if made is not None:
                folded[root] = made
                continue
        folded.append(point)
        if rank == 0:
            root = len(folded) - 1
        previous = rank
    return folded


class UCD:
    """The Unicode 3.2.0 database, as CPython 3.14 exposes it."""

    unidata_version = '3.2.0'

    def category(self, letter):
        return _at(_category_rows(), _want(letter))

    def bidirectional(self, letter):
        return _at(_bidi_rows(), _want(letter))

    def combining(self, letter):
        return _combining_map().get(_want(letter), 0)

    def decomposition(self, letter):
        point = _want(letter)
        syllable = point - 0xAC00
        if 0 <= syllable < 11172:
            parts = [0x1100 + syllable // 588,
                     0x1161 + (syllable % 588) // 28]
            tail = syllable % 28
            if tail:
                parts.append(0x11A7 + tail)
            return ' '.join('%X' % part for part in parts)
        return _decomposition_map().get(point, '')

    def normalize(self, form, text):
        if form == 'NFD' or form == 'NFC':
            table = _canonical_map()
            joins = None if form == 'NFD' else _composition_map()
        elif form == 'NFKD' or form == 'NFKC':
            table = _compat_map()
            joins = None if form == 'NFKD' else _composition_map()
        else:
            raise ValueError('invalid normalization form')
        ranks = _combining_map()
        points = []
        for letter in text:
            point = ord(letter)
            syllable = point - 0xAC00
            if 0 <= syllable < 11172:
                points.append(0x1100 + syllable // 588)
                points.append(0x1161 + (syllable % 588) // 28)
                tail = syllable % 28
                if tail:
                    points.append(0x11A7 + tail)
            else:
                points.extend(table.get(point, [point]))
        _order(points, ranks)
        if joins is not None:
            points = _meld(points, ranks, joins)
        return ''.join(chr(point) for point in points)


ucd = UCD()


def normalize(form, text):
    return ucd.normalize(form, text)


def category(letter):
    return ucd.category(letter)


def bidirectional(letter):
    return ucd.bidirectional(letter)
